'use strict';

const $ = (s, root = document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = prefix => `${prefix}_${crypto.randomUUID().slice(0, 8)}`;
const timestamp = () => new Date().toLocaleString('en-US', {hour12:false});
const paths = {
  dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
  agents:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8z M2 21v-2a7 7 0 0 1 14 0v2 M16 4a4 4 0 0 1 0 8 M22 21v-2a7 7 0 0 0-4-6',
  sessions:'M4 3h16v14H8l-4 4z M8 7h8 M8 11h6',
  memory:'M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h5',
  search:'M21 21l-6-6 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14z',
  objects:'M12 3l9 5-9 5-9-5z M3 12l9 5 9-5 M3 16l9 5 9-5',
  share:'M6 12l12-7 M6 12l12 7 M3 12a3 3 0 1 0 6 0 3 3 0 0 0-6 0 M16 5a3 3 0 1 0 6 0 3 3 0 0 0-6 0 M16 19a3 3 0 1 0 6 0 3 3 0 0 0-6 0',
  maintenance:'M14 5a5 5 0 0 0-6 6L2 17l5 5 6-6a5 5 0 0 0 6-6l-4 3-4-4z',
  cleanup:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',
  refresh:'M20 7a9 9 0 1 0 1 9 M20 2v6h-6',
  plus:'M12 5v14 M5 12h14',
  database:'M3 6c0-5 18-5 18 0s-18 5-18 0 M3 6v12c0 5 18 5 18 0V6 M3 12c0 5 18 5 18 0',
  clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l4 2',
  activity:'M2 12h5l3-8 4 16 3-8h5',
  check:'M5 12l4 4L19 6',
};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.database}"/></svg>`;
const pages = [
  ['overview','Database Overview','dashboard','OVERVIEW'], ['agents','Agents','agents','AGENTS'],
  ['sessions','Sessions','sessions','SESSIONS'], ['memory','Memories','memory','MEMORIES'],
  ['query','Query & Trace','search','QUERY & TRACE'], ['objects','Objects','objects','OBJECTS'],
  ['sharing','Sharing & Resolution','share','COLLABORATION'], ['maintenance','Memory Maintenance','maintenance','MAINTENANCE'],
  ['cleanup','Source Cleanup','cleanup','SOURCE CLEANUP'],
];
const descriptions = {
  overview:'View database health, object counts, and storage information.', agents:'Manage agent identities, roles, and workspace assignments.',
  sessions:'View registered sessions, their agents, and their goals.', memory:'Browse and manage memories, write events, and trace memory sources.',
  query:'Find memories and objects and inspect evidence and query execution.', objects:'Browse states, artifacts, object relationships, and governance records.',
  sharing:'Manage sharing contracts, share memories across agents, and resolve conflicts.', maintenance:'Evaluate, summarize, and compact memories. Review maintenance receipts.',
  cleanup:'Find memories by source and preview which records will be deleted or purged.',
};

function seed() {
  const agents = [
    {agent_id:'agent_assistant',role_profile:'General conversation assistant',tenant_id:'codesoul',workspace_id:'default'},
    {agent_id:'agent_research',role_profile:'Knowledge retrieval assistant',tenant_id:'codesoul',workspace_id:'default'},
    {agent_id:'agent_developer',role_profile:'Coding assistant',tenant_id:'codesoul',workspace_id:'default'},
    {agent_id:'agent_sandbox',role_profile:'Sandbox assistant',tenant_id:'codesoul',workspace_id:'sandbox'},
  ];
  const sessions = [
    {session_id:'session_a08f21',agent_id:'agent_assistant',goal:'Learn the user’s communication preferences'},
    {session_id:'session_b14e92',agent_id:'agent_research',goal:'Organize notes on vector search and memory management'},
    {session_id:'session_c32d07',agent_id:'agent_developer',goal:'Discuss the local application implementation'},
    {session_id:'session_d51a83',agent_id:'agent_assistant',goal:'Record project context and communication conventions'},
    {session_id:'session_test01',agent_id:'agent_sandbox',goal:'Test event ingestion and retrieval'},
  ];
  const contents = [
    ['The user prefers English responses and standard technical terminology.','agent_assistant','session_a08f21','preference','active'],
    ['The project runs locally with separate database and web services.','agent_developer','session_c32d07','fact','active'],
    ['Keep source events available so retrieved memories can be traced to their evidence and context.','agent_research','session_b14e92','fact','active'],
    ['Lead with the answer to technical questions, then explain the steps.','agent_assistant','session_a08f21','preference','active'],
    ['Tenants and workspaces define data scope. Agents and sessions identify the source.','agent_research','session_b14e92','fact','active'],
    ['The console organizes records by workspace, agent, and session.','agent_developer','session_c32d07','fact','active'],
    ['The user prefers concise tables and clear confirmation messages.','agent_assistant','session_d51a83','preference','active'],
    ['Previous communication preference: include detailed background in every reply.','agent_assistant','session_a08f21','preference','stale'],
    ['Events in the sandbox workspace are used to verify memory processing.','agent_sandbox','session_test01','observation','active'],
  ];
  const memories = contents.map(([content,agent_id,session_id,type,lifecycle_state],i) => ({
    memory_id:`mem_${['8f3a21b0','2e7c94d1','4b9e62a3','6a1d83f2','9c4b70e5','1d8a34c6','7e2f91b4','3b6d05a8','5a7f19c2'][i]}`,
    content, agent_id,session_id,type,lifecycle_state, tenant_id:'codesoul',workspace_id:i===8?'sandbox':'default',
    source_event_ids:[`evt_${String(i+1).padStart(8,'0')}`],created_at:`2026-11-22 ${String(10-Math.floor(i/4)).padStart(2,'0')}:${String(48-i*3).padStart(2,'0')}:12`,
    versions:[{version:1,change:'Created from an ingested event'}],payload:{text:content},
  }));
  return {agents,sessions,memories,mode:'test',lsn:1286,ingestTotal:memories.length,queryTotal:24,
    states:[{state_id:'state_91ae3b',tenant_id:'codesoul',workspace_id:'default',agent_id:'agent_developer',session_id:'session_c32d07',state_type:'workflow',state_key:'development_stage',state_value:'Frontend development',version:1}],
    artifacts:[{artifact_id:'art_7b3a92',tenant_id:'codesoul',workspace_id:'default',session_id:'session_b14e92',owner_agent_id:'agent_research',artifact_type:'document',mime_type:'text/markdown',content_ref:'inline',metadata:{body:'# Database Integration Notes\n\n## Data Scope\nOrganize records by tenant and workspace.\n\n## Memory Retrieval\nUse structured evidence to trace memory sources.'}}],
    edges:[{edge_id:'edge_8d12a6',src_object_id:'art_7b3a92',src_type:'artifact',dst_object_id:'mem_4b9e62a3',dst_type:'memory',edge_type:'derived_from'}],
    policies:[{policy_id:'policy_3c98b1',object_id:'art_7b3a92',object_type:'artifact',verified_state:'verified',policy_reason:'Verified against the original memory source'}],
    contracts:[{contract_id:'contract_5d28e1',tenant_id:'codesoul',workspace_id:'default',scope:'default',read_agents:['agent_research'],derive_agents:['agent_assistant']}],
    mutations:[],operations:[],extractions:[],events:memories.map(m=>({event_id:m.source_event_ids[0],memory_id:m.memory_id})),
  };
}
const STORAGE_KEY='plasmod-demo-v1';
let db;
try { db=JSON.parse(localStorage.getItem(STORAGE_KEY)); if(!db?.memories || !db?.operations) db=seed(); } catch { db=seed(); }
let scope='default', page='overview', tabs={}, search='', filters={}, pageIndex=1, queryResponse=null, drawerObject=null, drawerTab='object', maintenanceOperation='ingest', cleanupPreview=null, cleanupSignature='';
let modalReturnFocus=null, toastTimer;
const save = () => { try{localStorage.setItem(STORAGE_KEY,JSON.stringify(db));}catch{toast('Browser storage is unavailable. Changes will last until you leave this page.');} };
const scoped = rows => rows.filter(r=>!r.workspace_id || r.workspace_id===scope);
const agentIDs = () => scoped(db.agents).map(a=>a.agent_id);
const scopeSessions = () => db.sessions.filter(s=>agentIDs().includes(s.agent_id));
const scopeMemories = () => scoped(db.memories).filter(m=>m.lifecycle_state!=='forgotten');
const badge = value => {const colors={active:'green',ok:'green',completed:'green',verified:'green',test:'blue',stale:'orange',partial:'orange',forgotten:'red',failed:'red',prod:'orange',skipped:'orange'};return `<span class="badge ${colors[value]||''}">${esc(value)}</span>`;};
const btn=(label,action,primary=false,ico='',data='')=>`<button ${/\btype=/.test(data)?'':'type="button"'} class="btn ${primary?'primary':''}" data-action="${action}" ${data}>${ico?icon(ico):''}${label}</button>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
const panel=(title,body,extra='',cls='')=>`<section class="panel ${cls}"><div class="panel-header"><span class="panel-title">${title}</span>${extra}</div>${body}</section>`;
function infoList(rows){return `<dl class="info-list">${rows.map(([k,v])=>`<div class="info-row"><dt>${esc(k)}</dt><dd>${v}</dd></div>`).join('')}</dl>`;}
function stat(label,value,meta,ico){return `<article class="stat-card"><div class="stat-title">${label}<span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${esc(value)}</div><div class="stat-meta">${meta}</div></article>`;}
function heading(action=''){const current=pages.find(p=>p[0]===page);return `<div class="page-heading"><div><div class="eyebrow">${current[3]}</div><h1>${current[1]}</h1><p>${descriptions[page]}</p></div><div class="actions">${action}</div></div>`;}
function tabbar(items,key){return `<div class="tabs" role="tablist">${items.map(([id,name])=>`<button role="tab" aria-selected="${(tabs[key]||items[0][0])===id}" class="tab ${(tabs[key]||items[0][0])===id?'active':''}" data-action="tab" data-key="${key}" data-id="${id}">${name}</button>`).join('')}</div>`;}
function table(headers,rows,empty='No records in this scope'){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}"><div class="empty">${icon('database')}${empty}</div></td></tr>`}</tbody></table></div>`;}
function pagination(total){const n=Math.max(1,Math.ceil(total/6));pageIndex=Math.min(pageIndex,n);return `<div class="table-footer"><span>${total} ${total===1?'record':'records'}${total?` · Showing ${(pageIndex-1)*6+1}–${Math.min(pageIndex*6,total)}`:''}</span><div class="pagination"><button class="page-num" data-action="paginate" data-id="${pageIndex-1}" ${pageIndex<=1?'disabled':''} aria-label="Previous page">‹</button>${Array.from({length:n},(_,i)=>`<button class="page-num ${pageIndex===i+1?'current':''}" data-action="paginate" data-id="${i+1}">${i+1}</button>`).join('')}<button class="page-num" data-action="paginate" data-id="${pageIndex+1}" ${pageIndex>=n?'disabled':''} aria-label="Next page">›</button></div></div>`;}
function sliceRows(rows){pageIndex=Math.min(pageIndex,Math.max(1,Math.ceil(rows.length/6)));return rows.slice((pageIndex-1)*6,pageIndex*6);}
const detailLink=(id,label=id)=>`<button class="text-link mono" data-action="detail" data-id="${esc(id)}">${esc(label)}</button>`;
const searchBox=placeholder=>`<div class="search-field">${icon('search')}<input id="search" type="search" placeholder="${placeholder}" value="${esc(search)}" aria-label="${placeholder}"></div>`;
function selectFilter(name,options,placeholder){return `<select data-filter="${name}" aria-label="${placeholder}"><option value="">${placeholder}</option>${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${filters[name]===v?'selected':''}>${esc(l)}</option>`;}).join('')}</select>`;}
const filtered = rows=>rows.filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase()));

function overview(){
  const counts=[db.events.length,db.memories.length,db.states.length,db.artifacts.length,db.edges.length,db.memories.reduce((n,m)=>n+m.versions.length,0)];
  const total=counts.reduce((a,b)=>a+b,0);
  const names=['Events','Memories','States','Artifacts','Edges','Versions'], colors=['#204d70','#5091b6','#e99743','#a7bed1','#dce6ee','#718da4'];
  let accum=0;const gradient=counts.map((c,i)=>{const start=accum;accum+=c/total*100;return `${colors[i]} ${start}% ${accum}%`;}).join(',');
  const recent=scopeMemories().slice(0,5).map(m=>[detailLink(m.memory_id),`<div class="cell-title">${esc(m.content.slice(0,27))}${m.content.length>27?'…':''}</div><div class="cell-sub">${esc(m.type)}</div>`,`<span class="mono">${esc(m.agent_id)}</span>`,badge(m.lifecycle_state),`<span class="muted mono">${esc(m.created_at)}</span>`]);
  return heading(btn('Refresh status','refresh',false,'refresh'))+
    `<div class="health-banner"><strong><i class="dot"></i>Database healthy <span> · All nodes available and all writes visible</span></strong><span>Updated ${new Date().toLocaleTimeString('en-US',{hour12:false})}</span></div>`+
    `<div class="stats-grid">${stat('Total Events',counts[0].toLocaleString(),'<b>EVENTS</b> ingested','database')}${stat('Total Memories',counts[1].toLocaleString(),'<b>MEMORIES</b> including retained records','memory')}${stat('Total Queries',db.queryTotal,'<b>QUERIES</b> executed','search')}${stat('P95 Query Latency','12.4 ms','<b>LATENCY</b>','activity')}</div>`+
    `<div class="grid-two">${panel('Object Distribution',`<div class="panel-body"><div class="storage-layout"><div class="donut" style="background:conic-gradient(${gradient})"><div class="donut-inner"><strong>${total}</strong><small>TOTAL OBJECTS</small></div></div><div class="legend">${names.map((n,i)=>`<div class="legend-row"><span><i class="legend-dot" style="background:${colors[i]}"></i>${n}</span><b>${counts[i]}</b></div>`).join('')}</div></div></div>`,`<span class="badge">All workspaces</span>`)}${panel('Instance Information',`<div class="panel-body">${infoList([['Service Status','<span class="status-line"><i class="dot"></i> Healthy</span>'],['Mode',badge(db.mode)],['Storage Backend','<span class="mono">Badger + WAL</span>'],['Application HTTP','<span class="mono">127.0.0.1:19530</span>']])}<div class="watermark"><div class="watermark-label"><span>Write Visibility</span><span class="mono">${db.lsn} / ${db.lsn}</span></div><div class="progress"><span style="width:100%"></span></div></div></div>`,btn('System Details','overview-system',false))}</div>`+
    panel('Recent Memories',table(['Memory ID','Content Summary','Agent','Lifecycle','Created At'],recent),`<a class="text-link" href="#memory">View all</a>`)+
    `<div class="grid-two grid-equal">${panel('Service Nodes',table(['Node','Services','Status'],[['<span class="mono">plasmod-local-01</span>','Gateway / Memory / Query',badge('ok')]]),'<span class="panel-subtitle">TOPOLOGY</span>')}${panel('Performance',`<div class="panel-body">${infoList([['Total Writes',`<span class="mono">${db.ingestTotal}</span>`],['Query Latency P50 / P95 / P99','<span class="mono">4.2 / 12.4 / 21.8 ms</span>'],['Visibility Watermark',`<span class="mono">${db.lsn}</span>`]])}</div>`)}</div>`;
}
function systemView(){return heading(btn('Back to Overview','overview-main'))+`<div class="grid-two grid-equal">${panel('Services and Mode',`<div class="panel-body">${infoList([['Health',badge('ok')],['Application HTTP','<span class="mono">http://127.0.0.1:19530</span>'],['Admin HTTP','<span class="mono">http://127.0.0.1:9091</span>'],['gRPC','<span class="mono">127.0.0.1:19531</span>'],['Mode',`<select id="mode-select" class="mode-select"><option ${db.mode==='test'?'selected':''}>test</option><option ${db.mode==='prod'?'selected':''}>prod</option></select>`]])}</div>`)}${panel('Storage Configuration',`<div class="panel-body">${infoList([['mode','split'],['data_dir','<span class="mono">/data</span>'],['stores','<span class="mono">events, memories, objects</span>'],['badger_enabled',badge('true')],['wal_persistence',badge('true')]])}</div>`)}</div>`+panel('Indexes and Retrieval Segments',table(['Namespace','Index','Record Count','Retrieval Segment'],['default','sandbox'].map(ns=>[`<span class="mono">${ns}</span>`,'memory_vector_index',String(db.memories.filter(m=>m.workspace_id===ns&&m.lifecycle_state!=='forgotten').length),`<span class="mono">segment_${ns}_001</span>`])))+panel('Logs and Metrics',`<div class="panel-body">${infoList([['latest_lsn',String(db.lsn)],['visible_watermark',String(db.lsn)],['ingest_total',String(db.ingestTotal)],['query_total',String(db.queryTotal)],['storage_event_count',String(db.events.length)],['storage_memory_count',String(db.memories.length)]])}</div>`);}
function agentsView(){let rows=filtered(tabs.agents==='global'?db.agents:scoped(db.agents));if(filters.role)rows=rows.filter(a=>a.role_profile===filters.role);return heading(btn('Register Agent','new-agent',true,'plus'))+tabbar([['workspace','Workspace Agents'],['global','All Agents']],'agents')+panel('Agents',`<div class="toolbar">${searchBox('Search by agent ID or role')}${selectFilter('role',[...new Set(db.agents.map(a=>a.role_profile))],'All roles')}<span class="count">${tabs.agents==='global'?'All workspaces':'Current workspace'}</span></div>`+table(['Agent ID','Role','Tenant','Workspace','Actions'],sliceRows(rows).map(a=>[detailLink(a.agent_id),esc(a.role_profile),esc(a.tenant_id),`<span class="badge">${esc(a.workspace_id)}</span>`,`<button class="text-link" data-action="agent-sessions" data-id="${esc(a.agent_id)}">View sessions</button>`]))+pagination(rows.length));}
function sessionsView(){let rows=filtered(scopeSessions());if(filters.agent)rows=rows.filter(s=>s.agent_id===filters.agent);return heading(btn('Register Session','new-session',true,'plus'))+panel('Sessions',`<div class="toolbar">${searchBox('Search by session ID or goal')}${selectFilter('agent',agentIDs(),'All agents')}</div>`+table(['Session ID','Agent','Session Goal','Actions'],sliceRows(rows).map(s=>[detailLink(s.session_id),`<span class="mono">${esc(s.agent_id)}</span>`,esc(s.goal),`<button class="text-link" data-action="session-memories" data-id="${esc(s.session_id)}">View memories</button>`]))+pagination(rows.length));}
function memoryView(){let rows=filtered(scopeMemories());if(filters.agent)rows=rows.filter(m=>m.agent_id===filters.agent);if(filters.session)rows=rows.filter(m=>m.session_id===filters.session);if(filters.lifecycle)rows=rows.filter(m=>m.lifecycle_state===filters.lifecycle);return heading(btn('Find Receipt','find-mutation')+btn('Write Event','new-memory',true,'plus'))+panel('Memories',`<div class="toolbar">${searchBox('Search by memory content or ID')}${selectFilter('agent',agentIDs(),'All agents')}${selectFilter('session',scopeSessions().map(s=>s.session_id),'All sessions')}${selectFilter('lifecycle',['active','stale'],'All lifecycle states')}</div>`+table(['Memory / Source','Content','Agent / Session','Lifecycle','Actions'],sliceRows(rows).map(m=>[`<div>${detailLink(m.memory_id)}</div><div class="cell-sub mono">${esc(m.source_event_ids[0])}</div>`,`<div class="cell-title" style="white-space:normal;min-width:200px;max-width:320px;line-height:1.8">${esc(m.content)}</div><div class="cell-sub">${esc(m.type)}</div>`,`<span class="mono">${esc(m.agent_id)}</span><div class="cell-sub mono">${esc(m.session_id)}</div>`,badge(m.lifecycle_state),`<div class="actions"><button class="text-link" data-action="correct" data-id="${esc(m.memory_id)}">Correct</button><button class="text-link" data-action="forget" data-id="${esc(m.memory_id)}">Forget</button></div>`]))+pagination(rows.length));}

function queryView(){return heading()+tabbar([['query','Structured Query'],['recall','Memory Recall'],['trace','Object Trace']],'query')+(tabs.query==='trace'?panel('Trace by Object ID',`<div class="panel-body"><form id="trace-form"><div class="receipt-find"><input name="object_id" required placeholder="Enter a memory, artifact, or agent ID" aria-label="Object ID">${btn('View Details','submit',true,'search','type="submit"')}</div><div class="selection-tip">Copy an ID from Memories or Objects. Forgotten memories return 410 Gone.</div></form></div>`):`<div class="query-layout">${panel(tabs.query==='recall'?'Recall Parameters':'Query Parameters',`<div class="panel-body"><form id="query-form"><div class="form-grid">${field('query_text',tabs.query==='recall'?'Recall Question':'Query Question','textarea',{required:true,placeholder:'What are the user’s communication preferences?'})}${field('requester_agent_id','Requesting Agent','select',{options:agentIDs(),required:true})}${field('query_scope','Query Scope','text',{value:scope,required:true})}${field('top_k','Result Limit (top_k)','number',{value:3,min:1,max:100,required:true})}${tabs.query==='recall'?'':field('response_mode','Response Mode','select',{options:[['structured_evidence','Structured Evidence'],['objects_only','Object IDs Only']]})+field('target_object_ids','Target Object IDs (optional)','text',{placeholder:'Separate IDs with commas'})}</div><div class="form-actions">${btn('Run '+(tabs.query==='recall'?'Recall':'Query'),'submit',true,'search','type="submit"')}</div></form></div>`)}<div>${queryResponse?queryResult():panel('Query Results',`<div class="query-empty">${icon('search')}<h3>Start with a question</h3><p>Enter a query to see matching memories, evidence, and sources.</p></div>`)}</div></div>`);}
function queryResult(){const r=queryResponse;if(r.kind==='recall')return panel(`Recall Results <span class="panel-subtitle">${r.memories.length} visible references</span>`,resultsList(r.memories)+`<div class="panel-body"><div class="detail-section">algorithm_notes</div><div class="code-block">Matches content by keyword within the selected workspace and agent scope and returns up to ${r.top_k} records.</div><div class="detail-section">visible_memory_refs / payloads</div><pre class="code-block">${esc(JSON.stringify({visible_memory_refs:r.memories.map(m=>m.memory_id),payloads:r.memories.map(m=>({memory_id:m.memory_id,content:m.content}))},null,2))}</pre></div>`,badge('completed'));
  return panel('Query Results',`<div class="panel-body" style="padding-bottom:0"><div class="status-line">${badge('completed')}<span class="muted" style="font-size:11px">Found ${r.memories.length} objects · read_watermark_lsn: ${db.lsn}</span></div></div>`+(r.mode==='objects_only'?`<div class="panel-body"><pre class="code-block">${esc(JSON.stringify({objects:r.memories.map(m=>m.memory_id)},null,2))}</pre></div>`:resultsList(r.memories)+`<div class="panel-body"><div class="detail-section">Structured Evidence and Relationships</div><pre class="code-block">${esc(JSON.stringify({objects:r.memories.map(m=>m.memory_id),evidence:r.memories.map(m=>({memory_id:m.memory_id,source_event_ids:m.source_event_ids})),edges:db.edges.filter(e=>r.memories.some(m=>m.memory_id===e.dst_object_id||m.memory_id===e.src_object_id)),query_status:'completed',read_watermark_lsn:db.lsn},null,2))}</pre>${db.mode==='test'?`<div class="detail-section">Execution Trace</div>${Object.entries({main:[`Searched workspace ${scope}`,`Found ${r.memories.length} objects`],memory_pipeline:[`Recalled ${r.memories.length} memories`,'Matched content by keyword'],query:['Ran structured evidence query',`Evidence steps: ${r.memories.length}`],collaboration:['Checked sharing relationships for the requesting agent']}).map(([k,v])=>`<div class="chain-card"><strong>${k}</strong><ul>${v.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div>`).join('')}`:'<div class="note">Execution traces are available in test mode.</div>'}</div>`));
}
function resultsList(rows){return rows.length?rows.map(m=>`<article class="result-card"><div class="result-top">${detailLink(m.memory_id)}${badge(m.lifecycle_state)}</div><p>${esc(m.content)}</p><div class="result-meta"><span>${esc(m.agent_id)}</span><span>${esc(m.source_event_ids.join(', '))}</span></div></article>`).join(''):'<div class="empty">No matching visible memories</div>';}

const objectConfig={states:{name:'State',id:'state_id',headers:['State ID','Type','Key / Value','Agent','Version']},artifacts:{name:'Artifact',id:'artifact_id',headers:['Artifact ID','Type','MIME / Content Reference','Session','Actions']},edges:{name:'Relationship',id:'edge_id',headers:['Relationship ID','Source Object','Relationship Type','Target Object']},policies:{name:'Governance Record',id:'policy_id',headers:['Record ID','Object','Verification Status','Governance Reason']}};
function objectsView(){const type=tabs.objects||'states',cfg=objectConfig[type];let rows=filtered(type==='artifacts'?db.artifacts.filter(a=>scopeSessions().some(s=>s.session_id===a.session_id)):type==='states'?scoped(db.states):db[type]);if(type==='artifacts'&&filters.session)rows=rows.filter(a=>a.session_id===filters.session);if(type==='states'){if(filters.agent)rows=rows.filter(a=>a.agent_id===filters.agent);if(filters.session)rows=rows.filter(a=>a.session_id===filters.session);}if(type==='policies'&&filters.object)rows=rows.filter(p=>p.object_id===filters.object);return heading(btn('Register '+cfg.name,'new-object',true,'plus',`data-id="${type}"`))+tabbar(Object.entries(objectConfig).map(([k,v])=>[k,v.name]),'objects')+panel(cfg.name+'s',`<div class="toolbar">${searchBox('Search by ID or content')}${['states','artifacts'].includes(type)?selectFilter('session',scopeSessions().map(s=>s.session_id),'All sessions'):''}${type==='states'?selectFilter('agent',agentIDs(),'All agents'):''}${type==='policies'?selectFilter('object',[...new Set(db.policies.map(p=>p.object_id))],'All objects'):''}<span class="count">${['edges','policies'].includes(type)?'All workspaces':'Current workspace'}</span></div>`+table(cfg.headers,sliceRows(rows).map(o=>type==='states'?[detailLink(o.state_id),esc(o.state_type),`<span class="mono">${esc(o.state_key)}</span><div class="cell-sub">${esc(o.state_value)}</div>`,esc(o.agent_id),badge('v'+o.version)]:type==='artifacts'?[detailLink(o.artifact_id),esc(o.artifact_type),`<span class="mono">${esc(o.mime_type)}</span><div class="cell-sub">${esc(o.content_ref)}</div>`,esc(o.session_id),`<button class="text-link" data-action="detail" data-id="${esc(o.artifact_id)}">View Content</button>`]:type==='edges'?[detailLink(o.edge_id),detailLink(o.src_object_id),badge(o.edge_type),detailLink(o.dst_object_id)]:[detailLink(o.policy_id),detailLink(o.object_id),badge(o.verified_state),esc(o.policy_reason)]))+pagination(rows.length));}
function sharingView(){const tab=tabs.sharing||'contracts';return heading(tab==='contracts'?btn('Register Sharing Contract','new-contract',true,'plus'):'')+tabbar([['contracts','Sharing Contracts'],['share','Share Memory'],['conflict','Conflict Resolution']],'sharing')+(tab==='contracts'?panel('Sharing Contracts',`<div class="toolbar">${searchBox('Search by contract ID, scope, or agent')}${selectFilter('contractScope',[...new Set(db.contracts.map(c=>c.scope))],'All scopes')}<span class="count">Filter by scope</span></div>`+(()=>{const rows=filtered(db.contracts).filter(c=>!filters.contractScope||c.scope===filters.contractScope);return table(['Contract ID','Scope','Reader Agents','Deriving Agents','Workspace'],sliceRows(rows).map(c=>[detailLink(c.contract_id),esc(c.scope),c.read_agents.map(a=>`<span class="badge">${esc(a)}</span>`).join(' '),c.derive_agents.map(a=>`<span class="badge">${esc(a)}</span>`).join(' '),esc(c.workspace_id)]))+pagination(rows.length);})()):panel(tab==='share'?'Share Memory':'Submit Conflict Resolution',`<div class="panel-body"><div class="note">${tab==='share'?'Select the source and target agents and a sharing contract. The contract must allow both agents. Sharing with the same agent is skipped.':'Choose two memories from the same agent. Select which memory to keep and whether this resolves a factual conflict or a preference change.'}</div><form id="${tab}-form"><div class="form-grid">${tab==='share'?field('memory_id','Memory','select',{options:scopeMemories().map(m=>[m.memory_id,m.memory_id+' · '+m.content.slice(0,22)]),required:true})+field('from_agent_id','Source Agent','select',{options:agentIDs(),required:true})+field('to_agent_id','Target Agent','select',{options:agentIDs(),value:agentIDs()[1],required:true})+field('share_contract_id','Sharing Contract (optional)','select',{options:[['','No contract'],...scoped(db.contracts).map(c=>c.contract_id)]}):field('winner_id','Memory to Keep (winner_id)','select',{options:scopeMemories().map(m=>[m.memory_id,m.memory_id+' · '+m.content.slice(0,20)]),required:true})+field('loser_id','Memory to Retire (loser_id)','select',{options:scopeMemories().map(m=>[m.memory_id,m.memory_id+' · '+m.content.slice(0,20)]),required:true})+field('kind','Resolution Type','select',{options:[['factual_conflict','Factual Conflict'],['preference_change','Preference Change']]})}</div><div class="error-message" role="alert"></div><div class="form-actions">${btn(tab==='share'?'Share Memory':'Submit Resolution','submit',true,'','type="submit"')}</div><div id="action-result"></div></form></div>`));}

const operationNames={ingest:['Admission','Evaluate eligibility for admission'],update:['Update','Update memory state'],decay:['Decay','Evaluate memory decay'],summarize:['Summarize','Create a summary memory'],compress:['Compact','Compact source content']};
function maintenanceView(){return heading()+tabbar([['execute','Run Maintenance'],['receipt','Find Maintenance Receipt'],['extraction','Find Extraction Receipt']],'maintenance')+((tabs.maintenance||'execute')==='execute'?`<div class="maintenance-options">${Object.entries(operationNames).map(([k,v])=>`<button class="operation-card ${maintenanceOperation===k?'active':''}" data-action="operation" data-id="${k}"><strong>${v[0]}</strong><small>${k}</small></button>`).join('')}</div>`+panel(operationNames[maintenanceOperation][0],`<div class="panel-body"><form id="maintenance-form"><div class="form-grid">${field('agent_id','Agent Scope (optional)','select',{options:[['','All agents'],...agentIDs()]})}${field('session_id','Session Scope (optional)','select',{options:[['','All sessions'],...scopeSessions().map(s=>s.session_id)]})}<div class="field wide"><label>Memories (optional)</label><div class="checkbox-list">${scopeMemories().map(m=>`<label><input type="checkbox" name="memory_ids" value="${esc(m.memory_id)}"><span class="mono">${esc(m.memory_id)}</span><span class="muted">${esc(m.content.slice(0,26))}</span></label>`).join('')||'<p>No memories in this scope</p>'}</div><small>Leave the memory selection empty to process all memories within the current tenant, workspace, and any agent or session filters above.</small></div>${field('limit','Page Size (limit)','number',{value:100,min:1,max:1000,required:true})}${field('after_id','Cursor (after_id, optional)','text',{placeholder:'next_cursor from the previous receipt'})}${maintenanceOperation==='decay'?field('now_ts','Evaluation Time (now_ts, optional)','text',{placeholder:'2026-11-22T10:00:00+08:00'}):''}${maintenanceOperation==='update'?field('signals','Numeric Signals (optional JSON)','textarea',{value:'{}',hint:'Map memory IDs to numeric values, e.g. {"mem_xxx": 0.5}.',wide:true}):''}</div><div class="error-message" role="alert"></div><div class="form-actions">${btn('Run Maintenance','submit',true,'maintenance','type="submit"')}</div></form><div id="maintenance-result"></div></div>`):panel(tabs.maintenance==='extraction'?'Find Extraction by Source Event':'Find Maintenance Receipt by Operation ID',`<div class="panel-body"><form id="receipt-form" data-kind="${tabs.maintenance}"><div class="receipt-find"><input name="id" required placeholder="${tabs.maintenance==='extraction'?'Enter a source event ID, such as evt_00000001':'Enter a maintenance operation ID'}" aria-label="Receipt ID">${btn('Find Receipt','submit',true,'search','type="submit"')}</div></form><div id="receipt-result"></div><div class="selection-tip">Scope: codesoul / ${esc(scope)}. ${tabs.maintenance==='extraction'?'Events without an extraction receipt return 404.':'Use the operation_id returned by a maintenance run.'}</div></div>`));}
function cleanupView(){return heading()+`<div class="note danger-note">Preview the matching memories before deleting or purging them.</div>`+panel('Find by Source',`<div class="panel-body"><form id="cleanup-form"><div class="form-grid">${field('operation','Cleanup Method','select',{options:[['delete','Logical Delete (delete-by-source)'],['purge','Physical Purge (purge-by-source)']]})}${field('source_type','Source Identifier Type','select',{options:['event_id','reference_id','memory_id']})}${field('source_id','Source ID','text',{required:true,placeholder:'evt_00000008',wide:true})}${field('only_if_inactive','Purge Inactive Memories Only','select',{options:[['true','Yes (default)'],['false','No']]})}${field('include_memory_ids','Return Memory IDs','select',{options:[['true','Yes'],['false','No']]})}${field('async','Run Purge Asynchronously','select',{options:[['false','No (synchronous)'],['true','Yes']]})}</div><div class="form-actions">${btn('Preview Matches','submit',true,'search','type="submit"')}</div></form><div id="cleanup-result"></div></div>`,'<span class="badge orange">ADMIN</span>','danger-zone');}

function field(name,label,type='text',opts={}){const attrs=`name="${name}" id="field-${name}" ${opts.required?'required':''} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.max!==undefined?`max="${opts.max}"`:''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''}`;const value=opts.value??'';let input=type==='select'?`<select ${attrs}>${(opts.options||[]).map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select>`:type==='textarea'?`<textarea ${attrs} rows="4">${esc(value)}</textarea>`:`<input type="${type}" ${attrs} value="${esc(value)}">`;return `<div class="field ${opts.wide||type==='textarea'?'wide':''}"><label for="field-${name}">${label}${opts.required?' <span class="required">*</span>':''}</label>${input}${opts.hint?`<small>${esc(opts.hint)}</small>`:''}</div>`;}
function render(){const route=location.hash.slice(1)||'overview';page=pages.some(p=>p[0]===route)?route:'overview';$('#breadcrumb').textContent=pages.find(p=>p[0]===page)[1];$('#navigation').innerHTML=pages.map(([id,name,ico],i)=>`${i===0?'<div class="nav-group">WORKSPACE</div>':''}${i===6?'<div class="nav-group">ADMINISTRATION</div>':''}<a class="nav-item ${page===id?'active':''}" href="#${id}" ${page===id?'aria-current="page"':''}>${icon(ico)}<span>${name}</span>${id==='memory'?`<span class="nav-count">${scopeMemories().length}</span>`:''}</a>`).join('');const views={overview:()=>tabs.overview==='system'?systemView():overview(),agents:agentsView,sessions:sessionsView,memory:memoryView,query:queryView,objects:objectsView,sharing:sharingView,maintenance:maintenanceView,cleanup:cleanupView};$('#main').innerHTML=views[page]();if(page==='memory'&&db.mutations[0]?.workspace_id===scope){$('#main').innerHTML+=panel('Latest Correction or Forget Receipt','<div class="panel-body">'+receiptHTML(db.mutations[0])+'</div>');}}

function openModal(title,body,onSubmit){modalReturnFocus=document.activeElement;$('#overlay-root').innerHTML=`<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-header"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="Close">×</button></div><div class="modal-body"><form id="modal-form">${body}<div class="error-message" role="alert"></div><div class="form-actions">${btn('Cancel','close')}${btn('Confirm','submit',true,'','type="submit"')}</div></form></div></section></div>`;$('#modal-form').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));try{const result=onSubmit(data);if(result!==false){closeOverlay();render();}}catch(err){$('.error-message',e.currentTarget).textContent=err.message;}});setTimeout(()=>$('#modal-form input, #modal-form textarea, #modal-form select, #modal-form button')?.focus(),0);}
function closeOverlay(){$('#overlay-root').innerHTML='';drawerObject=null;modalReturnFocus?.focus();}
function findObject(id){for(const [collection,key]of [['memories','memory_id'],['agents','agent_id'],['sessions','session_id'],['states','state_id'],['artifacts','artifact_id'],['edges','edge_id'],['policies','policy_id'],['contracts','contract_id'],['events','event_id']]){const obj=db[collection].find(o=>o[key]===id);if(obj)return {obj,type:collection};}return null;}
function showDetail(id,tab='object'){
  const found=findObject(id);modalReturnFocus=document.activeElement;drawerObject=id;drawerTab=tab;
  let content='';
  if(!found) content='<div class="note">404 · Object not found.</div>';
  else if(found.obj.lifecycle_state==='forgotten') content='<div class="note danger-note">410 Gone · This memory is no longer accessible.</div>';
  else {
    const {obj,type}=found,edges=db.edges.filter(e=>e.src_object_id===id||e.dst_object_id===id),policies=db.policies.filter(p=>p.object_id===id);
    content=`<div class="tabs">${[['object','Object'],['edges','Relationship'],['versions','Version'],['policies','Governance'],['proof','Proof Steps']].map(([k,v])=>`<button class="tab ${tab===k?'active':''}" data-action="detail-tab" data-id="${k}">${v}</button>`).join('')}</div>`;
    if(tab==='object'){
      if(type==='memories')content+=`<div class="status-line">${badge(obj.lifecycle_state)}<span class="badge">${esc(obj.type)}</span></div><div class="detail-section">Memory Content</div><div class="detail-content">${esc(obj.content)}</div>${infoList([['Agent',esc(obj.agent_id)],['Session',esc(obj.session_id)],['Tenant / Workspace',`${esc(obj.tenant_id)} / ${esc(obj.workspace_id)}`],['Source Events',obj.source_event_ids.map(i=>detailLink(i)).join(' ')],['Created At',esc(obj.created_at)]])}<div class="form-actions">${btn('Mark Stale','stale',false,'',`data-id="${esc(id)}"`)}${btn('Share','share-memory',false,'',`data-id="${esc(id)}"`)}${btn('Correct','correct',true,'',`data-id="${esc(id)}"`)}${btn('Forget','forget',false,'',`data-id="${esc(id)}"`)}</div>`;
      else if(type==='artifacts'&&obj.content_ref==='inline')content+=`<div class="detail-section">Inline Artifact Preview</div><div class="markdown-preview">${markdown(obj.metadata?.body||'')}</div>`;
      content+=`<div class="detail-section">canonical_object</div><pre class="code-block">${esc(JSON.stringify(obj,null,2))}</pre>`;
    }else if(tab==='edges')content+=edges.length?table(['Relationship','Source Object','Target Object'],edges.map(e=>[esc(e.edge_type),detailLink(e.src_object_id),detailLink(e.dst_object_id)])):'<div class="empty">No relationships for this object</div>';
    else if(tab==='versions')content+=`<pre class="code-block">${esc(JSON.stringify(obj.versions||[],null,2))}</pre>`;
    else if(tab==='policies')content+=policies.length?table(['Verification Status','Reason'],policies.map(p=>[badge(p.verified_state),esc(p.policy_reason)])):'<div class="empty">No governance records for this object</div>';
    else content+=`<pre class="code-block">${esc(JSON.stringify(type==='memories'?obj.source_event_ids.map(event_id=>({step:'source_event',event_id,target_memory_id:id})):[],null,2))}</pre><div class="selection-tip">Source relationships for this object.</div>`;
  }
  $('#overlay-root').innerHTML=`<div class="overlay drawer-overlay"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-header"><div><div class="eyebrow">OBJECT TRACE</div><h2 id="dialog-title">Object Details</h2><div class="cell-sub mono">${esc(id)}</div></div><button class="icon-button" data-action="close" aria-label="Close">×</button></div><div class="modal-body">${content}</div></section></div>`;$('.drawer .icon-button').focus();
}
function markdown(text){return esc(text).split('\n').map(l=>l.startsWith('## ')?`<h2>${l.slice(3)}</h2>`:l.startsWith('# ')?`<h1>${l.slice(2)}</h1>`:l?`<p>${l}</p>`:'').join('');}
function newMemoryForm(id){const old=id?db.memories.find(m=>m.memory_id===id):null;if(old?.lifecycle_state==='forgotten'){toast('This memory has been forgotten.');return;}
  openModal(old?'Correct Memory':'Write Event',`<div class="note">${old?'Submit a replacement event to forget the original memory and receive a new replacement_id.':'Write an event to generate an event ID, a memory ID, and a link to its source.'}</div><div class="form-grid">${field('agent_id','Agent','select',{options:agentIDs(),value:old?.agent_id,required:true})}${field('session_id','Session','select',{options:scopeSessions().map(s=>s.session_id),value:old?.session_id,required:true})}${field('event_type','Event Type','text',{value:'observation',required:true})}${field('event_subtype','Event Subtype','text',{value:old?.type||'conversation_memory',required:true})}${field('event_id','Event ID (optional)','text',{placeholder:'Generated if left blank'})}${field('importance','Importance','number',{value:1,min:0,required:true})}${field('event_time','Event Time (Unix milliseconds)','number',{value:Date.now(),required:true})}${field('visibility','Visibility','select',{options:['private']})}${field('consistency','Consistency','select',{options:['strict']})}${field('payload','Payload JSON','textarea',{value:JSON.stringify({text:old?.content||''},null,2),required:true,hint:'Use payload.text for the memory content. Additional fields are allowed.',wide:true})}</div>`,d=>{let payload;try{payload=JSON.parse(d.payload);}catch{throw Error('Payload must be valid JSON.');}if(!payload||Array.isArray(payload)||typeof payload!=='object'||typeof payload.text!=='string'||!payload.text.trim())throw Error('Enter a payload object with a nonempty text field.');const session=db.sessions.find(s=>s.session_id===d.session_id);if(session?.agent_id!==d.agent_id)throw Error('Select a session that belongs to the current agent.');if(d.event_id&&db.events.some(e=>e.event_id===d.event_id))throw Error('This event ID already exists. Enter a new ID.');const m=addMemory(payload.text,d.agent_id,d.session_id,d.event_subtype,payload,d.event_id);db.events.find(e=>e.memory_id===m.memory_id).event={identity:{tenant_id:'codesoul',workspace_id:scope,event_id:m.source_event_ids[0]},actor:{agent_id:d.agent_id,session_id:d.session_id},time:{event_time:Number(d.event_time)},event:{event_type:d.event_type,event_subtype:d.event_subtype,importance:Number(d.importance)},access:{visibility:d.visibility,consistency:d.consistency},payload};if(old){old.lifecycle_state='forgotten';m.versions=[...old.versions,{version:old.versions.length+1,change:'Replaced by a correction',previous_memory_id:old.memory_id}];db.mutations.unshift({operation_id:uid('op'),tenant_id:'codesoul',workspace_id:scope,operation:'correct',status:'completed',forgotten_ids:[old.memory_id],replacement_id:m.memory_id});}save();toast(old?`Corrected · New memory ${m.memory_id}`:`Event written · ${m.memory_id}`);});
}
function addMemory(content,agent_id,session_id,type='observation',payload={text:content},eventId){const m={memory_id:uid('mem'),content,agent_id,session_id,type,payload,tenant_id:'codesoul',workspace_id:scope,lifecycle_state:'active',source_event_ids:[eventId||uid('evt')],created_at:timestamp(),versions:[{version:1,change:'Created from an ingested event'}]};db.memories.unshift(m);db.events.push({event_id:m.source_event_ids[0],memory_id:m.memory_id});db.lsn++;db.ingestTotal++;return m;}
function openObjectForm(type){const cfg=objectConfig[type];let fields='';if(type==='states')fields=field('agent_id','Agent','select',{options:agentIDs(),required:true})+field('session_id','Session','select',{options:scopeSessions().map(s=>s.session_id),required:true})+field('state_type','State Type','text',{value:'workflow',required:true})+field('state_key','State Key','text',{required:true})+field('state_value','State Value','text',{required:true,wide:true});if(type==='artifacts')fields=field('owner_agent_id','Owning Agent','select',{options:agentIDs(),required:true})+field('session_id','Session','select',{options:scopeSessions().map(s=>s.session_id),required:true})+field('artifact_type','Artifact Type','text',{value:'document',required:true})+field('mime_type','MIME Type','text',{value:'text/markdown',required:true})+field('content_ref','Content Reference','text',{value:'inline',required:true})+field('metadata','Metadata JSON','textarea',{value:'{"body": "# New Artifact"}',required:true,wide:true});if(type==='edges')fields=field('src_object_id','Source Object ID','text',{required:true})+field('src_type','Source Object Type','text',{value:'artifact',required:true})+field('dst_object_id','Target Object ID','text',{required:true})+field('dst_type','Target Object Type','text',{value:'memory',required:true})+field('edge_type','Relationship Type','text',{value:'derived_from',required:true});if(type==='policies')fields=field('object_id','Object ID','text',{required:true})+field('object_type','Object Type','text',{value:'memory',required:true})+field('verified_state','Verification Status','text',{value:'verified',required:true})+field('policy_reason','Governance Reason','textarea',{required:true});openModal('Register '+cfg.name,`<div class="form-grid">${field(cfg.id,cfg.id+' (optional)','text',{placeholder:'Generated if left blank'})}${fields}</div>`,d=>{if(d[cfg.id]&&findObject(d[cfg.id]))throw Error('This ID already exists.');if(d.metadata){try{d.metadata=JSON.parse(d.metadata);}catch{throw Error('Metadata must be valid JSON.');}if(!d.metadata||typeof d.metadata!=='object'||Array.isArray(d.metadata))throw Error('Metadata must be a JSON object.');}if(type==='states'||type==='artifacts'){if(db.sessions.find(s=>s.session_id===d.session_id)?.agent_id!==(d.agent_id||d.owner_agent_id))throw Error('The session does not belong to this agent.');d.tenant_id='codesoul';d.workspace_id=scope;}if(type==='edges'&&(!findObject(d.src_object_id)||!findObject(d.dst_object_id)))throw Error('The source or target object does not exist.');if(type==='policies'&&!findObject(d.object_id))throw Error('Object not found.');d[cfg.id]=d[cfg.id]||uid(cfg.id.replace('_id',''));if(type==='states')d.version=1;db[type].unshift(d);save();toast(cfg.name+' registered');});}
function receiptLookup(kind){openModal(kind==='mutation'?'Find Correction or Forget Receipt':'Operation Receipt',field('operation_id','Operation ID','text',{required:true,placeholder:'Enter an operation ID'}),d=>{const r=db.mutations.find(x=>x.operation_id===d.operation_id&&x.workspace_id===scope);if(!r)throw Error('404 · No receipt found in the current tenant and workspace.');$('.error-message',$('#modal-form')).innerHTML=`<pre class="code-block">${esc(JSON.stringify(r,null,2))}</pre>`;return false;});}

document.addEventListener('click',e=>{
  if(e.target.closest('a[href^="#"]')){filters={};search='';pageIndex=1;}
  const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id;
  if(action==='submit')return;
  if(action==='close')return closeOverlay();
  if(action==='refresh'){render();toast('Status refreshed');}
  if(action==='tab'){tabs[target.dataset.key]=id;search='';filters={};pageIndex=1;if(target.dataset.key==='query')queryResponse=null;render();}
  if(action==='paginate'){pageIndex=Number(id);render();}
  if(action==='overview-system'){tabs.overview='system';render();}
  if(action==='overview-main'){tabs.overview='main';render();}
  if(action==='detail')showDetail(id);
  if(action==='detail-tab')showDetail(drawerObject,id);
  if(action==='agent-sessions'){filters={agent:id};search='';pageIndex=1;location.hash='sessions';}
  if(action==='session-memories'){filters={session:id};search='';pageIndex=1;location.hash='memory';}
  if(action==='new-agent')openModal('Register Agent',`<div class="form-grid">${field('agent_id','Agent ID (optional)','text',{placeholder:'Generated if left blank'})}${field('role_profile','Role Description','text',{required:true})}${field('tenant_id','Tenant','text',{value:'codesoul',required:true})}${field('workspace_id','Workspace','select',{options:['default','sandbox'],value:scope,required:true})}</div>`,d=>{if(d.tenant_id!=='codesoul')throw Error('Tenant must be codesoul.');if(d.agent_id&&findObject(d.agent_id))throw Error('This agent ID already exists.');db.agents.unshift({...d,agent_id:d.agent_id||uid('agent')});save();toast('Agent registered');});
  if(action==='new-session')openModal('Register Session',`<div class="form-grid">${field('session_id','Session ID (optional)','text',{placeholder:'Generated if left blank'})}${field('agent_id','Agent','select',{options:agentIDs(),required:true})}${field('goal','Session Goal','textarea',{required:true})}</div>`,d=>{if(d.session_id&&findObject(d.session_id))throw Error('This session ID already exists.');db.sessions.unshift({...d,session_id:d.session_id||uid('session')});save();toast('Session registered');});
  if(action==='new-memory')newMemoryForm();
  if(action==='correct')newMemoryForm(id);
  if(action==='forget'){const m=db.memories.find(x=>x.memory_id===id);if(!m||m.lifecycle_state==='forgotten')return toast('Memory not found or already forgotten');openModal('Forget Memory',`<div class="note danger-note">Forget ${esc(id)}? The memory will be removed from the list, and its details will return 410 Gone.</div>${field('reason','Note (optional)','text',{placeholder:'Optional'})}`,()=>{m.lifecycle_state='forgotten';const op={operation_id:uid('op'),tenant_id:'codesoul',workspace_id:m.workspace_id,operation:'forget',status:'completed',forgotten_ids:[id]};db.mutations.unshift(op);save();toast('Memory forgotten · '+op.operation_id);});}
  if(action==='stale')openModal('Mark Memory as Stale',field('reason','Audit Reason','textarea',{value:'This memory no longer applies'}),d=>{const m=db.memories.find(x=>x.memory_id===id);m.lifecycle_state='stale';m.stale_reason=d.reason;save();toast('Memory marked as stale');});
  if(action==='find-mutation')receiptLookup('mutation');
  if(action==='new-object')openObjectForm(id);
  if(action==='new-contract')openModal('Register Sharing Contract',`<div class="form-grid">${field('contract_id','Contract ID (optional)','text')}${field('scope','Sharing Scope','text',{value:scope,required:true})}${field('read_agents','Agents Allowed to Read','text',{value:agentIDs()[1]||'',hint:'Separate agent IDs with commas'})}${field('derive_agents','Agents Allowed to Derive','text',{value:agentIDs()[0]||'',hint:'Separate agent IDs with commas'})}</div>`,d=>{const split=v=>v.split(',').map(x=>x.trim()).filter(Boolean);const read=split(d.read_agents),derive=split(d.derive_agents);if([...read,...derive].some(a=>!agentIDs().includes(a)))throw Error('Agents must be registered in the current workspace.');if(d.contract_id&&findObject(d.contract_id))throw Error('This contract ID already exists.');db.contracts.unshift({...d,contract_id:d.contract_id||uid('contract'),tenant_id:'codesoul',workspace_id:scope,read_agents:read,derive_agents:derive});save();toast('Sharing contract registered');});
  if(action==='share-memory'){closeOverlay();tabs.sharing='share';location.hash='sharing';setTimeout(()=>{const m=db.memories.find(x=>x.memory_id===id);const f=$('#share-form');if(f){f.elements.memory_id.value=id;f.elements.from_agent_id.value=m.agent_id;}},0);}
  if(action==='operation'){maintenanceOperation=id;render();}
  if(action==='execute-cleanup')executeCleanup();
});

document.addEventListener('input',e=>{if(e.target.id==='search'){const position=e.target.selectionStart;search=e.target.value;pageIndex=1;render();$('#search').focus();try{$('#search').setSelectionRange(position,position);}catch{}}if(e.target.closest('#cleanup-form'))invalidateCleanup();});
document.addEventListener('change',e=>{if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;pageIndex=1;render();}if(e.target.id==='workspace'){scope=e.target.value;search='';filters={};pageIndex=1;queryResponse=null;cleanupPreview=null;closeOverlay();render();toast('Switched to workspace '+scope);}if(e.target.id==='mode-select'){db.mode=e.target.value;queryResponse=null;save();render();toast('Mode updated');}if(e.target.closest('#cleanup-form'))invalidateCleanup();});
$('#menu-toggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
window.addEventListener('hashchange',()=>{search='';pageIndex=1;queryResponse=null;$('#sidebar').classList.remove('open');render();window.scrollTo(0,0);});
document.addEventListener('click',e=>{if(e.target.classList.contains('overlay'))closeOverlay();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeOverlay();$('#sidebar').classList.remove('open');}if(e.key==='Tab'&&$('.overlay')){const nodes=[...$('.overlay').querySelectorAll('button,input,select,textarea,a[href]')].filter(n=>!n.disabled&&n.offsetParent!==null);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});

document.addEventListener('submit',e=>{const form=e.target;if(form.id==='modal-form')return;e.preventDefault();const d=Object.fromEntries(new FormData(form));try{
  if(form.id==='trace-form')showDetail(d.object_id.trim());
  if(form.id==='query-form'){
    const ids=(d.target_object_ids||'').split(',').map(s=>s.trim()).filter(Boolean),requester=d.requester_agent_id;
    const terms=d.query_text.trim().toLowerCase().split(/[\s，。？！、,!?]+/).filter(Boolean);
    const matches=scopeMemories().filter(m=>m.workspace_id===d.query_scope&&m.agent_id===requester&&m.lifecycle_state==='active').filter(m=>ids.length?ids.includes(m.memory_id):terms.some(t=>m.content.toLowerCase().includes(t)||t.length>2&&[...t.matchAll(/[\u4e00-\u9fff]{2}/g)].some(x=>m.content.includes(x[0]))));
    queryResponse={kind:tabs.query==='recall'?'recall':'query',memories:matches.slice(0,Number(d.top_k)),mode:d.response_mode,top_k:Number(d.top_k)};db.queryTotal++;save();render();
  }
  if(form.id==='share-form'){
    const m=db.memories.find(x=>x.memory_id===d.memory_id);if(m.agent_id!==d.from_agent_id)throw Error('The source agent must own the selected memory.');
    if(d.from_agent_id===d.to_agent_id){$('#action-result').innerHTML=`<pre class="code-block">${esc(JSON.stringify({status:'skipped',reason:'Source and target agents are the same'},null,2))}</pre>`;return;}
    if(d.share_contract_id){const c=db.contracts.find(x=>x.contract_id===d.share_contract_id);if(c.workspace_id!==scope||c.scope!==scope||!c.read_agents.includes(d.to_agent_id)||!c.derive_agents.includes(d.from_agent_id))throw Error('403 · The contract does not allow this scope or these agents.');}
    const shared=addMemory(m.content,d.to_agent_id,scopeSessions().find(s=>s.agent_id===d.to_agent_id)?.session_id||'',m.type,m.payload);shared.source_event_ids=[...m.source_event_ids];shared.shared_from=m.memory_id;save();$('#action-result').innerHTML=`<div class="detail-section">Sharing Receipt</div><pre class="code-block">${esc(JSON.stringify({status:'ok',shared_memory_id:shared.memory_id},null,2))}</pre>`;toast('Memory shared');
  }
  if(form.id==='conflict-form'){
    if(d.winner_id===d.loser_id)throw Error('Choose different memories to keep and retire.');const winner=db.memories.find(m=>m.memory_id===d.winner_id),loser=db.memories.find(m=>m.memory_id===d.loser_id);if(winner.agent_id!==loser.agent_id)throw Error('Both memories must belong to the same agent.');const receipt={...d,tenant_id:'codesoul',workspace_id:scope,operation_id:uid('decision'),status:'completed',chain_name:'memory_pipeline'};$('#action-result').innerHTML=`<div class="detail-section">Resolution Receipt</div><pre class="code-block">${esc(JSON.stringify(receipt,null,2))}</pre>`;toast('Resolution receipt ready');
  }
  if(form.id==='maintenance-form')runMaintenance(form,d);
  if(form.id==='receipt-form'){
    const extraction=form.dataset.kind==='extraction';const receipt=(extraction?db.extractions:db.operations).find(x=>(extraction?x.event_id:x.operation_id)===d.id.trim()&&x.workspace_id===scope);$('#receipt-result').innerHTML=receipt?receiptHTML(receipt):`<div class="note">404 · ${extraction?'This event has no extraction receipt.':'No operation receipt found in this scope.'}</div>`;
  }
  if(form.id==='cleanup-form')previewCleanup(d);
}catch(err){const error=$('.error-message',form);if(error)error.textContent=err.message;else toast(err.message);}
});

function receiptHTML(r){return `<div class="detail-section">Operation Receipt ${badge(r.status)}</div>${r.items?`<div class="summary-strip">${[['Selected',r.selected_count],['Updated',r.updated_count],['Skipped',r.skipped_count],['Failed',r.failed_count]].map(([l,n])=>`<div class="summary-item"><span>${l}</span><strong>${n}</strong></div>`).join('')}</div>`:''}<pre class="code-block">${esc(JSON.stringify(r,null,2))}</pre>`;}
function runMaintenance(form,d){
  let signals={};if(d.signals){try{signals=JSON.parse(d.signals);}catch{throw Error('Signals must be valid JSON.');}if(!signals||Array.isArray(signals)||typeof signals!=='object'||Object.values(signals).some(n=>typeof n!=='number'||!Number.isFinite(n)))throw Error('Signals must be a JSON object mapping memory IDs to numbers.');}
  if(d.now_ts&&!/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|[+-]\d\d:\d\d)$/.test(d.now_ts))throw Error('Enter a timestamp in RFC 3339 format.');
  const selected=new FormData(form).getAll('memory_ids');let memories=scopeMemories().filter(m=>(!d.agent_id||m.agent_id===d.agent_id)&&(!d.session_id||m.session_id===d.session_id)&&(!selected.length||selected.includes(m.memory_id))).sort((a,b)=>a.memory_id.localeCompare(b.memory_id));
  if(d.after_id){const cursorIndex=memories.findIndex(m=>m.memory_id===d.after_id);if(cursorIndex<0)throw Error('The cursor is outside the current filter scope.');memories=memories.slice(cursorIndex+1);}
  const has_more=memories.length>Number(d.limit);memories=memories.slice(0,Number(d.limit));const items=memories.map(m=>({memory_id:m.memory_id,status:'skipped',reason:'No eligible state changes'})),produced=[];
  if(maintenanceOperation==='ingest')items.forEach(i=>i.reason='Memory already processed');
  if(maintenanceOperation==='update')items.forEach(i=>{if(signals[i.memory_id]!==undefined){const m=db.memories.find(x=>x.memory_id===i.memory_id);i.status='updated';i.reason='Updated using numeric signals';i.before={signal:m.algorithm_signal??0};m.algorithm_signal=signals[i.memory_id];i.after={signal:m.algorithm_signal};}});
  if(maintenanceOperation==='summarize'&&memories.length){const first=memories[0];const summary=addMemory('Summary: '+memories.map(m=>m.content).join(' ').slice(0,240),first.agent_id,first.session_id,'summary');produced.push(summary.memory_id);items.forEach(i=>{i.status='updated';i.reason='Included in summary';});}
  if(maintenanceOperation==='compress')items.forEach(i=>i.reason='Compaction criteria were not met. Source memory retained.');
  const r={operation_id:uid('maint'),tenant_id:'codesoul',workspace_id:scope,operation:maintenanceOperation,status:'completed',selected_count:items.length,updated_count:items.filter(i=>i.status==='updated').length,skipped_count:items.filter(i=>i.status==='skipped').length,failed_count:0,items,produced_ids:produced,has_more,...(has_more?{next_cursor:memories.at(-1).memory_id}:{})};db.operations.unshift(r);save();$('#maintenance-result').innerHTML=receiptHTML(r);toast('Maintenance complete. See the receipt for details.');
}
function invalidateCleanup(){cleanupPreview=null;cleanupSignature='';if($('#cleanup-result'))$('#cleanup-result').innerHTML='';}
function sourceMatches(d){return scoped(db.memories).filter(m=>d.source_type==='memory_id'?m.memory_id===d.source_id.trim():m.source_event_ids.includes(d.source_id.trim()));}
function previewCleanup(d){const matches=sourceMatches(d),eligible=d.operation==='purge'?matches.filter(m=>d.only_if_inactive==='false'||m.lifecycle_state!=='active'):matches.filter(m=>m.lifecycle_state!=='forgotten');cleanupPreview={d,matches:matches.map(m=>m.memory_id),eligible:eligible.map(m=>m.memory_id)};cleanupSignature=JSON.stringify(d);const r=d.operation==='purge'?{dry_run:true,matched:matches.length,skipped_active:matches.length-eligible.length,purgeable:eligible.length,purged:0,...(d.include_memory_ids==='true'?{memory_ids:eligible.map(m=>m.memory_id)}:{})}:{dry_run:true,matched:matches.length,deleted:0,memory_ids:matches.map(m=>m.memory_id)};$('#cleanup-result').innerHTML=`<div class="detail-section">Cleanup Preview ${badge('dry_run')}</div><pre class="code-block">${esc(JSON.stringify(r,null,2))}</pre>${btn(d.operation==='purge'?'Purge Memories':'Delete Memories','execute-cleanup',false,'cleanup',eligible.length?'':'disabled')}<div class="selection-tip">${eligible.length?'Only the memories in the preview will be affected.':'No eligible memories.'}</div>`;}
function executeCleanup(){if(!cleanupPreview)return;const current=Object.fromEntries(new FormData($('#cleanup-form')));if(JSON.stringify(current)!==cleanupSignature)return invalidateCleanup();const preview=cleanupPreview;openModal(preview.d.operation==='purge'?'Confirm Purge':'Confirm Delete',`<div class="note danger-note">This will ${preview.d.operation==='purge'?'purge':'logically delete'} ${preview.eligible.length} memories.</div><pre class="code-block">${esc(preview.eligible.join('\n'))}</pre>`,()=>{const count=preview.eligible.length;if(preview.d.operation==='purge')db.memories=db.memories.filter(m=>!preview.eligible.includes(m.memory_id));else db.memories.forEach(m=>{if(preview.eligible.includes(m.memory_id))m.lifecycle_state='forgotten';});save();cleanupPreview=null;cleanupSignature='';toast(`${preview.d.operation==='purge'?'Purged':'Deleted'} ${count} ${count===1?'memory':'memories'}`);setTimeout(()=>{const result=$('#cleanup-result');if(result)result.innerHTML=`<pre class="code-block">${esc(JSON.stringify({status:'completed',...(preview.d.operation==='purge'?{matched:preview.matches.length,skipped_active:preview.matches.length-count,purgeable:count,purged:count}:{matched:preview.matches.length,deleted:count,memory_ids:preview.eligible})},null,2))}</pre>`;},0);});}

render();
